def solution(input_str):
    def solve():
        import math

        lines = input_str.strip().split('\n')
        n = int(lines[0].strip())
        arr = list(map(int, lines[1].strip().split()))

        used = set()
        empty_pos = []
        fixed positions = []

        for i, x in enumerate(arr):
            idx = i + 1
            if x == -1:
                empty_pos.append(idx)
            elif x != idx:
                used.add(x)
            else:
                raise ValueError(f"Fixed point found at {idx} with value {x}")

        remaining_values = [v for v in range(1, n + 1) if v not in used]
        k = len(empty_pos)
        if len(remaining_values) != k:
            return "0\n"

        # dp[j][i] = number of ways to place i values into first j empty positions 
        # such that among those i values, j of them are "bad" (value == position in original array)
        # However, we pre-calc which empty positions have value = position

        bad_mask = 0
        for pos in empty_pos:
            if pos in remaining_values:
                bad_mask |= (1 << (pos - 1))

        # We will precompute dp[j][i]: number of ways to pick j positions from k total 
        # such that i of them are "matched" (value equals position in original array)

        # Precompute C(n, k)
        C = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            for j in range(i + 1):
                if j == 0 or j == i:
                    C[i][j] = 1
                else:
                    C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        # Let total there are k empty positions, and among them:
        # return_count = some of them may be "dangerous" where value == index
        danger_free_count = 0
        total_bad = 0
        for pos in empty_pos:
            if pos in remaining_values:
                total_bad += 1

        # The number of valid permutations = sum_{i=0}^{min(k, total_bad)} (-1)^i * C(k, i) * (k - i)! * C(total_bad, i)

        ans = 0
        for i in range(k + 1):
            if i > total_bad:
                break
            ways = C[k][i] * C[total_bad][i] % MOD
            fact = 1
            for j in range(k - i + 1):
                fact *= j
            term = ways * fact % MOD
            if i % 2 == 1:
                ans = (ans - term + MOD) % MOD
            else:
                ans = (ans + term) % MOD

        return f"{ans}\n"

    return solve()

